function applyImport(){if(!parsedImport)return;const isAdmin=db.sessionUser?.role==='admin',protectedValues=isAdmin?null:{name:draft.name,parent:draft.profile?.parent||'',recognized:draft.profile?.recognized,level:n(draft.profile?.level),xp:n(draft.profile?.xp),divineBonus:n(draft.profile?.divineBonus),gods:clone(draft.gods||{}),pointPools:clone(draft.pointPools||{attributes:0,skills:0})};draft=FichaParser.apply(draft,parsedImport);if(protectedValues){draft.name=protectedValues.name;draft.profile.parent=protectedValues.parent;draft.profile.recognized=protectedValues.recognized;draft.profile.level=protectedValues.level;draft.profile.xp=protectedValues.xp;draft.profile.divineBonus=protectedValues.divineBonus;draft.gods=protectedValues.gods;draft.pointPools=protectedValues.pointPools}else draft.profile.recognized=normalizeName(draft.profile.recognized)==='sim'?'Sim':'Não';markDirty(isAdmin?'Ficha atualizada por TXT':'Jogador atualizou a própria ficha por TXT');closeImport();render();toast('Ficha atualizada pelo texto',isAdmin?'Confira os campos e clique em Salvar alterações para registrar no histórico.':'Dados exclusivos da mestre foram preservados. Clique em Salvar alterações para enviar sua ficha.');}

let ocrDraft=[],ocrMedia=null;
async function readAbilityImage(){
 toast('Lendo a imagem','O reconhecimento pode levar alguns segundos.');
 const button=$('#ocr-abilities');button.disabled=true;button.textContent='Lendo imagem...';
 try{
   const result=await window.rpg.readAbilityImage(draft.id);if(result.canceled)return;
   const existing=new Set((draft.abilities||[]).map(a=>normalizeName(a.name)));
   const seen=new Set();let ignored=0;
   ocrDraft=(result.abilities||[]).filter(a=>{const key=normalizeName(a.name);if(!key||existing.has(key)||seen.has(key)){ignored++;return false}seen.add(key);return true});ocrMedia=result.media||null;
   if(!ocrDraft.length){toast('Nenhuma habilidade nova',ignored?'Todas as habilidades reconhecidas já estão cadastradas.':'Tente uma imagem mais nítida e com a tabela inteira.');return;}
   if(ignored)toast('Habilidades repetidas ignoradas',`${ignored} habilidade(s) que já existiam não serão adicionadas novamente.`);
   renderOcrPreview();$('#ocr-modal').classList.remove('hidden');
 }catch(error){const message=(error.message||String(error)).replace(/^Error invoking remote method '[^']+':\s*(Error:\s*)?/i,'');toast('Não foi possível ler a imagem',message,true)}finally{button.disabled=false;button.textContent='Ler tabela por imagem'}
}
function renderOcrPreview(){
 $('#ocr-results').innerHTML=ocrDraft.map((a,i)=>`<div class="ocr-row"><div class="field"><label>Habilidade</label><input data-ocr-i="${i}" data-ocr-key="name" value="${esc(a.name)}"></div><div class="field"><label>Efeito</label><textarea data-ocr-i="${i}" data-ocr-key="effect">${esc(a.effect)}</textarea></div><div class="field"><label>Nível</label><input type="number" data-ocr-i="${i}" data-ocr-key="level" value="${n(a.level)||1}"></div><button class="remove" data-remove-ocr="${i}">×</button></div>`).join('');
 document.querySelectorAll('[data-ocr-i]').forEach(el=>el.addEventListener('input',()=>{ocrDraft[n(el.dataset.ocrI)][el.dataset.ocrKey]=el.type==='number'?n(el.value):el.value}));
 document.querySelectorAll('[data-remove-ocr]').forEach(el=>el.addEventListener('click',()=>{ocrDraft.splice(n(el.dataset.removeOcr),1);renderOcrPreview()}));
}
function closeOcr(){$('#ocr-modal').classList.add('hidden')}
function applyOcr(){if(!ocrDraft.length)return;draft.abilities.push(...ocrDraft.map(a=>({name:a.name,effect:a.effect,level:n(a.level)||1,type:'active',useCurrent:0,useGoal:25})));if(ocrMedia)draft.gallery.push(ocrMedia);markDirty();closeOcr();render();toast('Habilidades adicionadas',`${ocrDraft.length} habilidade(s) foram escritas como Ativas. Confira a classificação e salve as alterações.`)}

let photoSettingsDraft=null;
async function openPhotoEditor(){
 if(!draft.portrait?.path)return;
 photoSettingsDraft={...(draft.portraitSettings||{fit:'cover',x:50,y:50,zoom:100})};
 $('#photo-fit').value=photoSettingsDraft.fit||'cover';$('#photo-x').value=n(photoSettingsDraft.x)||50;$('#photo-y').value=n(photoSettingsDraft.y)||50;$('#photo-zoom').value=n(photoSettingsDraft.zoom)||100;
 $('#photo-preview-image').src=await imageData(draft.portrait.path);updatePhotoPreview();$('#photo-modal').classList.remove('hidden');
}
function updatePhotoPreview(){
 photoSettingsDraft={fit:$('#photo-fit').value,x:n($('#photo-x').value),y:n($('#photo-y').value),zoom:n($('#photo-zoom').value)};
 const img=$('#photo-preview-image'),scale=photoSettingsDraft.zoom/100,tx=50-scale*photoSettingsDraft.x,ty=50-scale*photoSettingsDraft.y;img.style.objectFit=photoSettingsDraft.fit;img.style.objectPosition='center';img.style.transformOrigin='0 0';img.style.transform=`translate(${tx}%,${ty}%) scale(${scale})`;
 $('#photo-x-value').textContent=`${photoSettingsDraft.x}%`;$('#photo-y-value').textContent=`${photoSettingsDraft.y}%`;$('#photo-zoom-value').textContent=`${photoSettingsDraft.zoom}%`;
}
