function renderUsersManager(){
 if(db.sessionUser?.role!=='admin')return;
 const users=db.users||[],characters=db.characters||[];
 const layout=$('#users-modal .users-layout'),userSection=$('#users-list')?.closest('section'),ownerSection=$('#character-owners')?.closest('section');
 if(layout)layout.classList.add('users-by-player');if(ownerSection)ownerSection.classList.add('hidden');
 $('#users-list').innerHTML='<h3>Jogadores e personagens</h3>'+users.map(user=>{const owned=characters.filter(character=>character.ownerUserId===user.id),available=characters.filter(character=>character.ownerUserId!==user.id);return `<article class="user-assignment-card"><div class="user-assignment-head"><div><strong>${esc(user.name)}</strong><small>@${esc(user.username)}</small></div><div><span class="role-badge ${user.role==='admin'?'admin':''}">${user.role==='admin'?'Mestre':'Jogador'}</span>${user.id!==db.sessionUser.id?`<button class="danger small-btn delete-user-button" data-delete-user="${user.id}">Excluir usuário</button>`:''}</div></div><div class="assigned-characters"><span>Personagens deste usuário</span>${owned.length?owned.map(character=>`<b>${esc(character.name)}</b>`).join(''):'<em>Nenhum personagem atribuído</em>'}</div><div class="field assign-character-field"><label>Atribuir personagem</label><select data-assign-to-user="${user.id}"><option value="">Selecione uma ficha...</option>${available.map(character=>`<option value="${character.id}">${esc(character.name)}</option>`).join('')}</select></div></article>`}).join('');
 document.querySelectorAll('[data-assign-to-user]').forEach(el=>el.addEventListener('change',async()=>{if(!el.value)return;try{db=await window.rpg.assignCharacter(el.value,el.dataset.assignToUser);draft=clone(current());renderUsersManager();renderSidebar();toast('Personagem atribuído','A ficha foi colocada na conta selecionada.')}catch(error){toast('Não foi possível atribuir',error.message,true)}}));
 document.querySelectorAll('[data-delete-user]').forEach(el=>el.addEventListener('click',async()=>{if(!confirm('Excluir este usuário? As fichas dele voltarão para a conta da mestre.'))return;try{db=await window.rpg.deleteUser(el.dataset.deleteUser);renderUsersManager();toast('Usuário excluído')}catch(error){toast('Não foi possível excluir',error.message,true)}}));
}
