let onlineReloadTimer,onlineReloadBusy=false,onlinePendingNotice=false,pendingOnlineSnapshot=null,onlinePointerDown=false;
document.addEventListener('pointerdown',()=>{onlinePointerDown=true},true);
for(const eventName of ['pointerup','pointercancel'])document.addEventListener(eventName,()=>{onlinePointerDown=false;setTimeout(()=>{if(pendingOnlineSnapshot){const latest=pendingOnlineSnapshot;pendingOnlineSnapshot=null;applyOnlineSnapshot(latest)}},0)},true);
function applyOnlineSnapshot(latest){
 if(!db)return;
 const focused=document.activeElement,editing=focused?.matches('input:not([readonly]):not([disabled]),textarea:not([readonly]):not([disabled]),select:not([disabled])');
 if(editing||onlinePointerDown||document.querySelector('.modal:not(.hidden)')){pendingOnlineSnapshot=latest;return}
 if(JSON.stringify([db.characters,db.settings,db.users])===JSON.stringify([latest.characters,latest.settings,latest.users]))return;
 if(dirty){db.characters=latest.characters;db.users=latest.users;const changed=latest.characters.find(c=>c.id===currentId)?._remoteVersion!==draft?._remoteVersion;if(changed&&!onlinePendingNotice){onlinePendingNotice=true;toast('A ficha recebeu uma atualização','Suas alterações foram preservadas. Ao salvar, mudanças em campos diferentes serão combinadas.')}renderSidebar();return}
 onlinePendingNotice=false;const selected=currentId;db=latest;
 const next=db.characters.find(c=>c.id===selected&&!c.archived)||db.characters.find(c=>!c.archived);
 currentId=next?.id||null;draft=next?clone(next):null;savedSharedSolos=sharedSolos();
 if(!next)activeView=isMaster()?'archived':'empty';else if(activeView==='empty')activeView='sheets';
 render();clean();
}
document.addEventListener('focusout',()=>setTimeout(()=>{if(pendingOnlineSnapshot){const latest=pendingOnlineSnapshot;pendingOnlineSnapshot=null;applyOnlineSnapshot(latest)}},0));
window.rpg.onOnlineChange?.(()=>{
 clearTimeout(onlineReloadTimer);onlineReloadTimer=setTimeout(async()=>{
  if(!db||onlineReloadBusy)return;onlineReloadBusy=true;
  try{
   const latest=await window.rpg.load();applyOnlineSnapshot(latest);
  }catch(error){toast('Conexão online',error.message||String(error),true)}finally{onlineReloadBusy=false}
 },200);
});
